#include "combat.h"
#include "actions.h"
#include <cstdio>
#include <memory>
#include <stdexcept>
#ifndef EXPECT_CONTROL
#define EXPECT_CONTROL 1
#endif
using namespace tactics;
static void require(bool b,const char*s){if(!b){std::printf("RYTH_TRIBUTE_FAIL %s\n",s);throw std::runtime_error(s);}}
static void drain(unsigned goal){volatile unsigned n=1;while(bc::fuel_remaining()>goal)for(int k=0;k<8;++k)n=n*1664525+k;}
int main(){Geometry geo;Memory memory;std::unique_ptr<World>ptr;int phase=0,group=-1;const Pos stance{9,8},camp{17,8},bank{13,8},altar{12,8};while(true){try{const int team=bc::detail::sdk_my_team();if(bc::is_draft()){auto old=bc::draft::current_draft(bc::team::ally);for(auto pick:{team==0?bc::champion_draft::ryth:bc::champion_draft::vendetta,bc::champion_draft::willow,bc::champion_draft::stellar})if(std::find(old.begin(),old.end(),pick)==old.end()){bc::draft::pick(pick);break;}}else if(phase<9&&int(bc::self().champion_name())==(team==0?0:2)){if(!geo.initialized){geo.initialize();bc::end_turn();continue;}const Pos goal=team==0?stance:phase<3?camp:bank;if(!geo.goal_field(goal,team==1&&phase<2?1:0)||bc::fuel_remaining()<65000){bc::end_turn();continue;}if(!ptr)ptr=std::make_unique<World>(geo,memory);auto&w=*ptr;w.refresh();require(w.self.alive,"actual scripted actor alive");if(team==1){if(group<0)for(unsigned i=0;i<geo.groups.size();++i)if(geo.groups[i].spawns.front().pos==camp)group=i;require(group>=0,"actual native cluster");if(phase==0){if(distance(w.self.pos,camp)<=1)phase=1;else if(auto next=w.toward(camp,1))require(w.me.move_absolute(sdk(*next)),"actual captor approach");}else if(phase==1){if(w.groups[group].state==Lifecycle::Reward)phase=2;else if(!w.groups[group].camps.empty()){auto c=w.camp(w.groups[group].camps.front().id);require(c.has_value(),"actual visible cluster");w.me.attack(*c);}}else if(phase==2){if(w.self.gems>0)phase=3;else if(w.self.pos!=camp)if(auto next=w.toward(camp))require(w.me.move_absolute(sdk(*next)),"actual capture entry");}else if(phase==3){if(w.self.pos!=bank){if(auto next=w.toward(bank))require(w.me.move_absolute(sdk(*next)),"actual tribute approach");}else{require(w.self.gems>0,"native captured bag");w.me.submit_gems(sdk(altar));require(w.me.is_submitting_gems(),"actual native tribute started");std::printf("RYTH_TRIBUTE_STARTED round=%d bag=%d\n",w.round,w.self.gems);phase=4;}}}else{if(phase==0){if(w.self.pos==stance)phase=1;else if(auto next=w.toward(stance))require(w.me.move_absolute(sdk(*next)),"actual Ryth approach");}else{const Actor*target=nullptr;for(const auto&e:w.enemies)if(e.channel==Channel::Tribute)target=&e;if(target){require(target->hp>100&&distance(w.self.pos,target->pos)<=4,"actual nonlethal target in Ryth range");require(w.spells[0].kind==3&&w.spells[0].duration==1&&w.spells[0].enemies&&w.spells[0].ready,"actual native Ryth metadata");const int real_score=w.enemy_score;w.enemy_score=int(bc::constants::winning_gems)-target->gems;drain(40000);const auto before=bc::fuel_remaining();auto proposal=combat_proposal(w,memory,false,60000);const auto after=bc::fuel_remaining();require(w.round==int(bc::round_number()),"one actual owner epoch");const bool deciding=proposal&&proposal->priority==Priority::Deciding&&proposal->action.kind==Kind::CastChampion&&proposal->action.slot==0;auto handle=w.champion(target->id);require(handle&&handle->is_submitting_gems(),"actual target channel before action");if constexpr(EXPECT_CONTROL){require(deciding,"cheap Ryth stun must stop deciding projected threshold without optional AoE search");auto result=execute(w,proposal->action);require(result.success,"actual native Ryth cast accepted");require(!handle->is_submitting_gems()&&handle->buffs().has_stun()&&handle->health()>0,"actual nonlethal stun interrupts actual Tribute");}else{require(!deciding,"frozen control lacks cheap deciding stun");require(handle->is_submitting_gems(),"control performs no cast and actual channel remains");}std::printf("RYTH_TRIBUTE_PASS mode=%d round=%d actualScore=%d projectedScore=%d bag=%d entry=%u exit=%u priority=%d\n",EXPECT_CONTROL,w.round,real_score,w.enemy_score,target->gems,unsigned(before),unsigned(after),proposal?int(proposal->priority):-1);phase=9;}}}}}catch(const std::exception&e){std::printf("RYTH_TRIBUTE_EXCEPTION %s\n",e.what());phase=9;}bc::end_turn();}}
